#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn spot_checks_against_the_static_table() {
        let b = record(1).unwrap();
        assert_eq!((b.damage, b.radius, b.wind_pct, b.fuse_ms, b.category), (50, 48, 100, 9000, 2));
        let g = record(6).unwrap();
        assert_eq!((g.damage, g.radius, g.wind_pct, g.default_fuse_ms, g.fuse_ms), (50, 50, 0, 5000, 0));
        let s = record(23).unwrap();
        assert_eq!((s.damage, s.radius, s.fuse_ms, s.category), (75, 153, 20000, 3));
    }
}
